import { mkdir, rm, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';

/**
 * Where processed images are kept. Keys are generated by the server
 * (`events/<random>.webp`), never taken from a client.
 */
export interface StorageAdapter {
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  delete(key: string): Promise<void>;
  /** Public URL the browser loads the object from. */
  urlFor(key: string): string;
}

const KEY_PATTERN = /^(events|avatars)\/[a-f0-9]{32}\.webp$/;

/**
 * Files on local disk, served by the API under /uploads. Fine for one instance
 * (development, a single VM). With several instances every instance needs the
 * same directory (a shared volume) or an object-storage adapter instead.
 */
export class LocalStorage implements StorageAdapter {
  readonly root: string;

  constructor(
    dir: string,
    private readonly publicBaseUrl: string,
  ) {
    this.root = resolve(dir);
  }

  private pathOf(key: string): string {
    if (!KEY_PATTERN.test(key)) throw new Error('Invalid storage key');
    const full = resolve(this.root, key);
    // On top of the pattern check: never leave the upload directory.
    if (!full.startsWith(this.root + sep)) throw new Error('Invalid storage key');
    return full;
  }

  async put(key: string, data: Buffer): Promise<void> {
    const file = this.pathOf(key);
    await mkdir(dirname(file), { recursive: true });
    await writeFile(file, data, { flag: 'wx' }); // never overwrite: keys are random and unique
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathOf(key), { force: true });
  }

  urlFor(key: string): string {
    return `${this.publicBaseUrl}/uploads/${key}`;
  }
}
